<?php
declare(strict_types=1);require_once __DIR__.'/common.php';$user=qa_require_user();qa_post();$qid=(int)($_POST['question_id']??0);$desc=trim((string)($_POST['description']??''));if($qid<1||$desc==='')exit('Invalid answer.');$pdo=db();$pdo->beginTransaction();try{$check=$pdo->prepare('SELECT id FROM qa_questions WHERE id=?');$check->execute([$qid]);if(!$check->fetch())throw new RuntimeException('Question not found.');$pdo->prepare('INSERT INTO qa_answers(question_id,user_id,description,code_snippet,code_language) VALUES(?,?,?,?,?)')->execute([$qid,(int)$user['id'],$desc,trim((string)($_POST['code_snippet']??''))?:null,trim((string)($_POST['code_language']??''))?:null]);$aid=(int)$pdo->lastInsertId();$file=qa_image_upload();if($file)qa_save_attachment($pdo,$qid,$aid,(int)$user['id'],$file);$pdo->commit();qa_redirect('view.php?id='.$qid);}catch(Throwable $e){$pdo->rollBack();http_response_code(400);exit(e($e->getMessage()));}
